general.customPopupCss:
:root[data-theme="dark"] {
  --accent-color: #89b4fa;
  --accent-color-light: rgba(137, 180, 250, 0.8);
  --accent-color-lighter: rgba(137, 180, 250, 0.7);
  --background-color: #1e1e2e;
  --background-color-dark1: #313244;
  --background-color-light: #313244;
  --gloss-image-background-color: #313244;
  --link-color: var(--accent-color);
  --text-color: #cdd6f4;
  --text-color-light1: #a6adc8;
  --text-color-light2: #6c7086;
  --text-color-light3: #7f849c;
  --text-color-light4: #6c7086;
  --reason-text-color: #bac2de;
  --pronunciation-annotation-color: #cdd6f4;
  --headword-text-color-rare: #d4dcf6;
  --light-border-color: #313244;
  --medium-border-color: #45475a;
  --dark-border-color: #585b70;
  --tag-text-color: #11111b;
  --tag-border-color: transparent;
  --tag-default-background-color: #cdd6f4;
  --tag-name-background-color: #cba6f7;
  --tag-expression-background-color: #f9e2af;
  --tag-popular-background-color: #89b4fa;
  --tag-frequent-background-color: #89dceb;
  --tag-archaism-background-color: #eba0ac;
  --tag-dictionary-background-color: #b4befe;
  --tag-frequency-background-color: #a6e3a1;
  --tag-part-of-speech-background-color: #cdd6f4;
  --tag-search-background-color: #bac2de;
  --tag-pronunciation-dictionary-background-color: #b4befe;
  --sidebar-background-color: #181825;
  --sidebar-button-background-color: transparent;
  --sidebar-button-background-color-hover: #9399b2;
  --sidebar-button-background-color-active: #7f849c;
  --sidebar-button-danger-background-color: transparent;
  --sidebar-button-danger-background-color-hover: #e27687;
  --sidebar-button-danger-background-color-active: #de6175;
  --sidebar-button-icon-color: #bac2de;
  --sidebar-button-disabled-icon-color: #7f849c;
  --sidebar-button-danger-icon-color: #eba0ac;
  --scrollbar-thumb-color: #6c7086;
  --scrollbar-track-color: #313244;
  --scrollbar-inverse-thumb-color: #585b70;
  --scrollbar-inverse-track-color: #cdd6f4;
  --progress-bar-track-color: #313244;
  --progress-bar-indicator-color: var(--accent-color);
  --entry-current-indicator-color: var(--accent-color);
  --notification-text-color: #cdd6f4;
  --notification-background-color: #313244;
  --notification-background-color-light: #9399b2;
  --notification-background-color-lighter: #585b70;
  --notification-shadow-color: rgba(255, 255, 255, 0.25);
  --action-button-hover-color: #313244;
  --action-button-active-color: #45475a;
  --input-background-color: #313244;
  --menu-item-hover-color: #45475a;
  --menu-item-active-color: #45475a;
  --shadow-color: rgba(0, 0, 0, 0.35);
  --atamadaka: #f38ba8;
  --heiban: #94e2d5;
  --nakadaka: #fab387;
  --odaka: #a6e3a1;
  --kifuku: #cba6f7;

  .gloss-sc-ul li {
    border-color: #7f849c;
  }

  button:hover:focus-visible,
  button:hover:not(:focus-visible),
  .button:hover:focus-visible,
  .button:hover:not(:focus-visible),
  button:active:focus-visible,
  button:active:not(:focus-visible),
  .button:active:focus-visible,
  .button:active:not(:focus-visible) {
    --button-current-content-color: #11111b;
  }

  span[data-sc-content="example-keyword"] {
    color: #a6e3a1 !important;
  }

  span[data-sc-class="form-special"] {
    color: #f38ba8 !important;
  }

  div[data-sc-class="extra-label"],
  span[data-sc-content="attribution-footnote"] {
    color: #7f849c !important;
  }

  span[data-sc-content="part-of-speech-info"],
  span[data-sc-content="forms-label"] {
    background-color: #a6adc8 !important;
    color: #11111b !important;
  }

  span[data-sc-content="misc-info"] {
    background-color: #eba0ac !important;
    color: #11111b !important;
  }

  span[data-sc-content="field-info"] {
    background-color: #cba6f7 !important;
    color: #11111b !important;
  }

  span[data-sc-content="dialect-info"] {
    background-color: #a6e3a1 !important;
    color: #11111b !important;
  }

  span[data-sc-content="lang-source-wasei"] {
    background-color: #fab387 !important;
    color: #11111b !important;
  }

  div[data-sc-content="info-gloss"] {
    border-color: #a6e3a1 !important;
    background-color: color-mix(in srgb, #a6e3a1 5%, transparent) !important;
  }

  div[data-sc-content="sense-note"] {
    border-color: #f9e2af !important;
    background-color: color-mix(in srgb, #f9e2af 5%, transparent) !important;
  }

  div[data-sc-content="lang-source"] {
    border-color: #cba6f7 !important;
    background-color: color-mix(in srgb, #cba6f7 5%, transparent) !important;
  }

  div[data-sc-content="xref"] {
    border-color: #74c7ec !important;
    background-color: color-mix(in srgb, #74c7ec 5%, transparent) !important;
    & span[data-sc-content="reference-label"] {
      color: #74c7ec !important;
    }
  }

  div[data-sc-content="antonym"] {
    border-color: #eba0ac !important;
    background-color: color-mix(in srgb, #eba0ac 5%, transparent) !important;
    & span[data-sc-content="reference-label"] {
      color: #eba0ac !important;
    }
  }

  td[data-sc-class="form-pri"] > span {
    color: #11111b !important;
    background: radial-gradient(#a6e3a1 50%, white 100%) !important;
  }

  td[data-sc-class="form-irr"] > span {
    color: #11111b !important;
    background: radial-gradient(#eba0ac 50%, white 100%) !important;
  }

  td[data-sc-class="form-out"] > span,
  td[data-sc-class="form-old"] > span {
    color: #11111b !important;
    background: radial-gradient(#74c7ec 50%, white 100%) !important;
  }

  td[data-sc-class="form-rare"] > span {
    color: #11111b !important;
    background: radial-gradient(#cba6f7 50%, white 100%) !important;
  }

  [data-dictionary^="新和英大辞典"] details summary {
    color: #7f849c !important;
  }

  [data-dictionary^="新和英大辞典"] details summary:hover {
    color: #9399b2 !important;
  }

  [data-dictionary^="新和英大辞典"] details > *:not(summary) {
    border-left-color: #45475a !important;
  }

  [style*="color: rgb(229, 0, 127)"] {
    color: #f5c2e7 !important;
  }

  [style*="color: rgb(255, 255, 255)"][style*="background-color: rgb(92, 107, 192)"] {
    color: #11111b !important;
    background-color: #cba6f7 !important;
  }

  [style*="color: rgb(255, 255, 255)"][style*="background-color: rgb(76, 175, 80)"] {
    background-color: #a6e3a1 !important;
    color: #11111b !important;
  }

  [style*="color: rgb(224, 224, 224)"] {
    color: #cdd6f4 !important;
  }
}

[data-dictionary^="Jitendex"] [data-sc-content="attribution"],
[data-dictionary^="Jitendex"] [data-sc-content="forms"],
[data-dictionary^="どんなとき"] .tag:first-child,
[data-dictionary^="Scripting Japan (Slang)"] .gloss-sc-div:has(> .gloss-link),
[data-sc-content="attribution-footnote"],
[data-dictionary^="Scripting Japan (Slang)"] [style="font-weight: bold; font-size: 1.2em; color: rgb(224, 224, 224); margin-bottom: 10px;"],
[data-dictionary^="JMdict"] .tag[title^="JMdict Sense"],
[data-dictionary^="JMdict"]:has(.tag[title="other surface forms and readings"]) {
  display: none !important;
}

.definition-item-inner.collapsible.collapsed {
  max-height: calc(1em * var(--collapsible-definition-line-count) * var(--line-height) + 3px);
}

[data-dictionary^="Jitendex"] .definition-tag-list.tag-list {
  height: 0;
}

[data-details="other surface forms and readings"].tag,
.gloss-sc-table-container {
  margin-bottom: 3px;
}

[style*="font-size: 130%"],
.gloss-sc-ul[style*="font-size: 1.3em"],
.gloss-sc-div[style*="font-size: 1.3em"],
[style*="font-size: 1.2em"],
div[data-sc-content="xref-content"],
div[data-sc-content="antonym-content"] {
  font-size: 1em !important;
}

[style*="font-size: 180%"] {
  font-size: 1.5em !important;
}

div[data-sc-content="example-sentence-a"],
div[data-sc-content="xref-content"] {
  font-size: 1em !important;
}

[data-dictionary="Scripting Japan (Slang)"] {
  [style="margin-bottom: 12px;"] {
    margin-bottom: 0 !important;
  }

  [style="margin-left: 20px; margin-bottom: 14px;"] {
    margin-left: 0 !important;
    margin-bottom: 0 !important;
  }

  [style="margin-top: 8px; margin-left: 8px; margin-bottom: 12px;"] {
    margin: 0 8px 0 !important;
  }

  [style="font-style: italic; font-size: 13px; margin-top: 6px; margin-left: 32px;"] {
    margin-top: 0 !important;
  }

  [style="font-size: 13px; margin-top: 8px; padding-left: 12px;"] {
    margin-top: 2px !important;
    padding-left: 8px !important;
    padding-right: 8px;
  }
}

[style="font-weight: bold; font-size: 13px; color: rgb(255, 255, 255); background-color: rgb(92, 107, 192); padding: 3px 8px;"] {
  border-radius: var(--tag-border-radius);
  font-size: var(--tag-font-size) !important;
  font-weight: var(--tag-font-weight) !important;
  padding: calc(2.5em / var(--font-size-no-units)) 0.375em calc(2.5em / var(--font-size-no-units))
    0.375em !important;
}

[style="font-weight: bold; font-size: 12px; color: rgb(255, 255, 255); background-color: rgb(76, 175, 80); margin-right: 8px; padding: 2px 6px;"] {
  border-radius: var(--tag-border-radius);
  font-size: var(--tag-font-size) !important;
  font-weight: var(--tag-font-weight) !important;
  padding: calc(2.5em / var(--font-size-no-units)) 0.375em calc(2.5em / var(--font-size-no-units))
    0.375em !important;
}

/* Heiban */
html:has(
  .entry-current .headword[data-is-primary="true"][data-pronunciation-categories^="heiban"]
) {
  --pitch-tag-color: var(--heiban);
}

.pronunciation:has(.pronunciation-downstep-notation[data-downstep-position="0"]) {
  --pronunciation-annotation-color: var(--heiban);
}

.pronunciation:has(.pronunciation-downstep-notation[data-downstep-position="0"])
  .pronunciation-downstep-notation-number {
  color: var(--heiban);
}

/* Atamadaka */
html:has(
  .entry-current .headword[data-is-primary="true"][data-pronunciation-categories^="atamadaka"]
) {
  --pitch-tag-color: var(--atamadaka);
}

.pronunciation:has(.pronunciation-downstep-notation[data-downstep-position="1"]) {
  --pronunciation-annotation-color: var(--atamadaka);
}

.pronunciation:has(.pronunciation-downstep-notation[data-downstep-position="1"])
  .pronunciation-downstep-notation-number {
  color: var(--atamadaka);
}

/* Nakadaka */
html:has(
  .entry-current .headword[data-is-primary="true"][data-pronunciation-categories^="nakadaka"]
) {
  --pitch-tag-color: var(--nakadaka);
}

.pronunciation:has(.pronunciation-mora:not(:last-child)[data-pitch-next="low"]):has(
    .pronunciation-downstep-notation:not([data-downstep-position="1"])
  ) {
  --pronunciation-annotation-color: var(--nakadaka) !important;
}

.pronunciation:has(.pronunciation-mora:not(:last-child)[data-pitch-next="low"]):has(
    .pronunciation-downstep-notation:not([data-downstep-position="1"])
  )
  .pronunciation-downstep-notation-number {
  color: var(--nakadaka) !important;
}

/* Odaka */
html:has(.entry-current .headword[data-is-primary="true"][data-pronunciation-categories^="odaka"]) {
  --pitch-tag-color: var(--odaka);
}

.pronunciation:has(.pronunciation-mora:last-child[data-pitch-next="low"]):not(
    :has(.pronunciation-downstep-notation[data-downstep-position="1"])
  ) {
  --pronunciation-annotation-color: var(--odaka);
}

.pronunciation:has(.pronunciation-mora:last-child[data-pitch-next="low"]):not(
    :has(.pronunciation-downstep-notation[data-downstep-position="1"])
  )
  .pronunciation-downstep-notation-number {
  color: var(--odaka);
}

/* Kifuku */
html:has(
  .entry-current .headword[data-is-primary="true"][data-pronunciation-categories^="kifuku"]
) {
  --pitch-tag-color: var(--kifuku);
}

/* Nasal Mora */
.pronunciation-nasal-indicator {
  border: 0.1em solid var(--nasal-color);
  width: 0.35em;
  height: 0.35em;
  right: -0.1em;
  top: 0.225em;
}

/* Devoiced Mora */
.pronunciation-devoice-indicator {
  display: none;
}

.pronunciation-mora[data-devoice="true"] {
  color: var(--devoiced-color);
}

dictionaries.styles:
span[title] {
    cursor: help;
}

ul[data-sc-content="sense-groups"] {
    list-style-type: "＊";
}

li[data-sc-content="sense-group"],
li[data-sc-content="forms"] {
    padding-left: 0.25em;
}

div[data-sc-content="sense-group"],
li[data-sc-content="sense-group"]:first-child {
    margin-top: 0.1em;
}

li[data-sc-content="sense-group"] + li[data-sc-content="sense-group"],
div[data-sc-content="forms"],
li[data-sc-content="forms"] {
    margin-top: 0.5em;
}

li[data-sc-content="sense"] {
    padding-left: 0.25em;
    & ul[data-sc-content="glossary"] {
        list-style-type: none;
        padding-left: 0.25em;
    }
}

span[data-sc-class="tag"] {
    border-radius: 0.3em;
    font-size: 0.8em;
    font-weight: bold;
    margin-right: 0.5em;
    padding: 0.2em 0.3em;
    vertical-align: text-bottom;
    word-break: keep-all;
}

span[data-sc-content="part-of-speech-info"] {
    background-color: #565656;
    color: white;
}

span[data-sc-content="misc-info"] {
    background-color: brown;
    color: white;
}

span[data-sc-content="field-info"] {
    background-color: purple;
    color: white;
}

span[data-sc-content="dialect-info"] {
    background-color: green;
    color: white;
}

span[data-sc-content="lang-source-wasei"] {
    background-color: orange;
    color: black;
    margin-left: 0.5em;
    margin-right: 0;
}

span[data-sc-content="forms-label"] {
    background-color: #565656;
    color: white;
}

ul[data-sc-content="glossary"] {
    list-style-type: disc;
}

span[data-sc-content="registered-trademark"] {
    vertical-align: super;
    font-size: 0.6em;
}

div[data-sc-class="extra-box"] {
    border-radius: 0.4rem;
    border-style: none none none solid;
    border-width: calc(3em / var(--font-size-no-units, 14));
    margin-bottom: 0.5rem;
    margin-top: 0.5rem;
    padding: 0.5rem;
    width: fit-content;
}

div[data-sc-class="extra-content"] {
    margin-left: 0.5rem;
}

div[data-sc-content="info-gloss"] {
    border-color: green;
    background-color: color-mix(in srgb, green 5%, transparent);
}

div[data-sc-content="sense-note"] {
    border-color: goldenrod;
    background-color: color-mix(in srgb, goldenrod 5%, transparent);
}

div[data-sc-content="lang-source"] {
    border-color: purple;
    background-color: color-mix(in srgb, purple 5%, transparent);
}

div[data-sc-content="xref"] {
    border-color: #1A73E8;
    background-color: color-mix(in srgb, #1A73E8 5%, transparent);
    & span[data-sc-content="reference-label"] {
        color: #1A73E8;
    }
}

div[data-sc-content="antonym"] {
    border-color: brown;
    background-color: color-mix(in srgb, brown 5%, transparent);
    & span[data-sc-content="reference-label"] {
        color: brown;
    }
}

div[data-sc-content="example-sentence"] {
    border-color: var(--text-color, var(--fg, #333));
    background-color: color-mix(in srgb, var(--text-color, var(--fg, #333)) 5%, transparent);
}

div[data-sc-content="extra-info"] {
    margin-left: 0.5em;
}

div[data-sc-class="extra-label"] {
    color: #777;
    font-size: 0.8em;
    font-style: italic;
}

span[data-sc-content="reference-label"] {
    font-size: 0.8em;
    margin-right: 0.5rem;
}

div[data-sc-content="xref-content"],
div[data-sc-content="antonym-content"] {
    font-size: 1.3em;
}

div[data-sc-content="xref-glossary"],
div[data-sc-content="antonym-glossary"] {
    font-size: 0.8rem;
}

div[data-sc-content="example-sentence-a"] {
    font-size: 1.3em;
}

div[data-sc-content="example-sentence-b"] {
    font-size: 0.8em;
}

span[data-sc-content="example-keyword"] {
    color: color-mix(in srgb, lime, var(--text-color, var(--fg, #333)));
}

span[data-sc-content="attribution-footnote"] {
    color: #777;
    font-size: 0.8em;
    margin-left: 0.25rem;
    vertical-align: top;
}

div[data-sc-content="graphic"] {
    margin-bottom: 0.5rem;
    margin-top: 0.5rem;
    & .gloss-image-container {
        border: solid calc(42em / var(--font-size-no-units, 14)) var(--text-color, var(--fg, #333));
        border-radius: 3%;
    }
}

div[data-sc-content="graphic-attribution"] {
    font-size: 70%;
    margin-top: 0.25rem;
}

/* The "forms" section may be contained in a <div> or a <li> depending on the content of the entry. */
div[data-sc-content="forms"],
li[data-sc-content="forms"] {
    & ul {
        font-size: 1.2em;
        list-style-type: circle;
    }
    & table {
        margin-top: 0.2em;
    }
    & tr {
        border-width: 1px;
    }
    & th {
        border-width: 1px;
        font-weight: normal;
        text-align: left;
    }
    & td {
        border-width: 1px;
        text-align: center;
        & span {
            clip-path: circle();
            display: block;
            font-weight: bold;
            padding: 0 0.5em;
        }
    }
}

/* For the display of sense number restrictions in forms tables */
th[data-sc-content="forms-row-senses"],
tr[data-sc-content="forms-col-senses-row"] th {
    text-align: center;
}

tr[data-sc-content="forms-header-row"] th {
    font-size: 1.2em;
    text-align: center;
    vertical-align: text-bottom;
    & span[data-sc-class="old-character"] {
        text-emphasis-style: dot;
    }
}

span[data-sc-class="form-special"] {
    color: crimson;
}

td[data-sc-class="form-pri"] > span {
    color: white;
    background: radial-gradient(green 50%, white 100%);
    &::before {
        content: "△";
    }
}

td[data-sc-class="form-irr"] > span {
    color: white;
    background: radial-gradient(crimson 50%, white 100%);
    &::before {
        content: "✕";
    }
}

td[data-sc-class="form-out"] > span {
    color: white;
    background: radial-gradient(blue 50%, white 100%);
    &::before {
        content: "古";
    }
}

td[data-sc-class="form-old"] > span {
    color: white;
    background: radial-gradient(blue 50%, white 100%);
    &::before {
        content: "旧";
    }
}

td[data-sc-class="form-rare"] > span {
    color: white;
    background: radial-gradient(purple 50%, white 100%);
    &::before {
        content: "▽";
    }
}

td[data-sc-class="form-valid"] > span {
    color: var(--background-color, var(--canvas, #f8f9fa));
    background: radial-gradient(var(--text-color, var(--fg, #333)) 50%, white 100%);
    &::before {
        content: "◇";
    }
}

div[data-sc-content="attribution"] {
    font-size: 0.7em;
    text-align: right;
}

div[data-sc-content="redirect-glossary"] {
    font-size: 180%;
    margin-top: 0.2em;
}

.gloss-content span,
[data-sc-content] span {
  text-wrap: pretty;
}

.gloss-content span[data-sc-devoice="true"],
[data-sc-content] span[data-sc-devoice="true"] {
  display: inline-block;
  min-width: 1.05em;
  height: 1.05em;
  line-height: 1;
  text-align: center;
  border: 1px dashed currentColor;
  border-radius: 999px;
  box-sizing: border-box;
  margin-left: 0.03em;
  margin-right: 0.03em;
}

.gloss-content span[data-sc-agent-recovery="true"],
[data-sc-content] span[data-sc-agent-recovery="true"] {
  display: inline-block;
  align-items: center;
  text-align: center;
  width: 1.15em;
  height: 1.15em;
  margin-left: 0.35em;
  line-height: 1.25em;
  vertical-align: middle;
  border: 1px solid currentColor;
  border-radius: 999px;
  box-sizing: border-box;
  color: #b36b00;
  font-size: 0.78em;
  font-weight: 700;
  cursor: help;
  transform: translateY(-3px);
}

.gloss-content [data-sc-definition-root="true"],
[data-sc-content] [data-sc-definition-root="true"] {
  font-size: 0.95em;
}

.gloss-content [data-sc-definition-heading="true"],
[data-sc-content] [data-sc-definition-heading="true"] {
  margin-top: 0.5em;
}

.gloss-content span[data-sc-pitch-mark="true"],
[data-sc-content] span[data-sc-pitch-mark="true"] {
  margin-left: 0.15em;
  margin-right: 0.15em;
  font-weight: 700;
  color: #ff6666;
}

.gloss-content span[data-sc-variant-label="true"],
[data-sc-content] span[data-sc-variant-label="true"] {
  font-size: 0.78em;
  font-weight: 500;
  border: 1px solid gray;
